('operating_model_governance', '{"bodies":[{"key":"council","nameEn":"Programme Steering Committee","nameAr":"اللجنة التوجيهية للبرنامج","roleEn":"The Programme Steering Committee is the highest authority over the Office. It endorses the National Environment Strategy (NES) and its reviews, approves the annual data and monitoring programme and the annual report, and directs the Programme Director.","roleAr":"اللجنة التوجيهية للبرنامج هي السلطة العليا على المكتب. تعتمد الاستراتيجية الوطنية للبيئة ومراجعاتها، وتقر برنامج البيانات والرصد السنوي والتقرير السنوي، وتوجه مدير البرنامج.","decisionsEn":["Endorsement of the National Environment Strategy and its mid-term review","Approval of the annual data and monitoring programme","Approval of the annual report of the Office","Positions on matters escalated by the Programme Director"],"decisionsAr":["اعتماد الاستراتيجية الوطنية للبيئة ومراجعتها النصفية","إقرار برنامج البيانات والرصد السنوي","اعتماد التقرير السنوي للمكتب","البت في الموضوعات التي يرفعها مدير البرنامج"],"cadence":"quarterly","members":[{"en":"Chair of the Programme Steering Committee","ar":"رئيس اللجنة التوجيهية للبرنامج"},{"en":"Representatives of the member entities","ar":"ممثلو الجهات الأعضاء"},{"en":"Programme Director, Rapporteur","ar":"مدير البرنامج، مقرراً"}],"escalatesTo":null,"escalationEn":"Final authority within the programme; matters beyond its mandate go to the national steering level.","escalationAr":"السلطة النهائية داخل البرنامج، وما يتجاوز اختصاصها يُرفع إلى مستوى التوجيه الوطني.","sort":0},{"key":"secretary_general","nameEn":"The Programme Director","nameAr":"مدير البرنامج","roleEn":"Directs the Office, chairs the Executive Committee of the Office and the Strategy Steering Committee, approves the operating model and its processes, and represents the Office before government entities.","roleAr":"يدير المكتب، ويرأس اللجنة التنفيذية للمكتب ولجنة توجيه الاستراتيجية، ويعتمد نموذج التشغيل وعملياته، ويمثل المكتب أمام الجهات الحكومية.","decisionsEn":["Approval of the operating model, the process architecture and the RACI","Allocation of budget and people between sectors","Release of data products that depart from the pre-announced calendar","Escalations from the Executive Committee of the Office and the Strategy Steering Committee"],"decisionsAr":["اعتماد نموذج التشغيل وهيكل العمليات ومصفوفة المسؤوليات","توزيع الموازنة والكوادر بين القطاعات","الإذن بإصدار المنتجات البيانية الخارجة عن التقويم المعلن","التصعيدات الواردة من اللجنة التنفيذية للمكتب ولجنة توجيه الاستراتيجية"],"cadence":"weekly","members":[{"en":"Programme Director","ar":"مدير البرنامج"},{"en":"Office of the Programme Director","ar":"مكتب مدير البرنامج"},{"en":"Strategy and Performance Sector","ar":"قطاع الاستراتيجية والأداء"}],"escalatesTo":"council","escalationEn":"Matters of policy, mandate or national significance are escalated to the Programme Steering Committee.","escalationAr":"تُرفع المسائل السياساتية أو المتعلقة بالاختصاص أو ذات الأهمية الوطنية إلى اللجنة التوجيهية للبرنامج.","sort":1},{"key":"executive_committee","nameEn":"Executive Committee of the Office","nameAr":"اللجنة التنفيذية للمكتب","roleEn":"The sector heads with the Programme Director run the Office week to week: cross-sector priorities, the operating calendar, interface disputes between units and the operational KPI scorecard.","roleAr":"يدير رؤساء القطاعات مع مدير البرنامج المكتب أسبوعاً بأسبوع: الأولويات العابرة للقطاعات، والتقويم التشغيلي، والخلافات على الواجهات بين الوحدات، وبطاقة مؤشرات الأداء التشغيلي.","decisionsEn":["Approval of changes to unit-to-unit interfaces proposed by unit heads","Monthly review of the operational KPI scorecard","Sequencing of the annual planning and reporting calendar","Resolution of ownership questions between sectors"],"decisionsAr":["اعتماد تعديلات الواجهات بين الوحدات المقترحة من رؤساء الوحدات","المراجعة الشهرية لبطاقة مؤشرات الأداء التشغيلي","ترتيب تقويم التخطيط والتقارير السنوي","حسم مسائل الملكية بين القطاعات"],"cadence":"monthly","members":[{"en":"Programme Director, Chair","ar":"مدير البرنامج، رئيساً"},{"en":"Head of the Strategy and Performance Sector","ar":"رئيس قطاع الاستراتيجية والأداء"},{"en":"Head of the Data and Knowledge Sector","ar":"رئيس قطاع البيانات والمعرفة"},{"en":"Head of the Regulatory Affairs Sector","ar":"رئيس قطاع الشؤون التنظيمية"},{"en":"Director of Foresight and Risk","ar":"مدير الاستشراف والمخاطر"},{"en":"Director of Partnerships and International Commitments","ar":"مدير الشراكات والالتزامات الدولية"},{"en":"Head of the Corporate Services Sector","ar":"رئيس قطاع الخدمات المؤسسية"}],"escalatesTo":"secretary_general","escalationEn":"Anything the committee cannot settle by consensus is decided by the Programme Director.","escalationAr":"ما تعجز اللجنة عن حسمه بالتوافق يبت فيه مدير البرنامج.","sort":2},{"key":"regulatory_review_panel","nameEn":"Regulatory Review Panel","nameAr":"لجنة المراجعة التنظيمية","roleEn":"Reviews changes in environmental regulation that affect the Office and its partner entities: the regulatory register, the impact of new and amended instruments on the NES themes, and the follow up of compliance findings, with the regulators represented.","roleAr":"تراجع التغييرات في التنظيمات البيئية التي تمس المكتب والجهات الشريكة: السجل التنظيمي، وأثر الأدوات الجديدة والمعدلة على محاور الاستراتيجية الوطنية للبيئة، ومتابعة نتائج الامتثال، بتمثيل الجهات التنظيمية.","decisionsEn":["Entries and status changes in the regulatory register","Which regulatory changes need an impact note for the themes","Referral of compliance findings to the owning entity","The quarterly regulatory change brief to leadership"],"decisionsAr":["القيود وتغييرات الحالة في السجل التنظيمي","التغييرات التنظيمية التي تستوجب مذكرة أثر على المحاور","إحالة نتائج الامتثال إلى الجهة المالكة","موجز التغييرات التنظيمية الربعي للقيادة"],"cadence":"quarterly","members":[{"en":"Head of the Regulatory Affairs Sector, Chair","ar":"رئيس قطاع الشؤون التنظيمية، رئيساً"},{"en":"Director of Regulatory Compliance Monitoring","ar":"مدير متابعة الامتثال التنظيمي"},{"en":"Director of Regulatory and Legislative Review","ar":"مدير المراجعة التنظيمية والتشريعية"},{"en":"Director of Water Security","ar":"مدير الأمن المائي"},{"en":"Representatives of the partner regulators","ar":"ممثلو الجهات التنظيمية الشريكة"}],"escalatesTo":"executive_committee","escalationEn":"Disagreements with an entity on a regulatory interpretation are escalated to the Executive Committee of the Office.","escalationAr":"تُرفع الخلافات مع الجهات حول تفسير تنظيمي إلى اللجنة التنفيذية للمكتب.","sort":3},{"key":"data_governance_board","nameEn":"Data Governance Board","nameAr":"مجلس حوكمة البيانات","roleEn":"Owns the data standards, the classification scheme, the data-sharing agreements and the access controls across the Office and the entities it serves.","roleAr":"يملك معايير البيانات، ومخطط التصنيف، واتفاقيات تبادل البيانات، وضوابط الوصول على مستوى المكتب والجهات التي يخدمها.","decisionsEn":["Adoption of data standards and common definitions","Approval of data-sharing agreements with entities","Classification of new datasets and exceptions to the access rules","Remediation plans for data quality gaps"],"decisionsAr":["اعتماد معايير البيانات والتعاريف الموحدة","اعتماد اتفاقيات تبادل البيانات مع الجهات","تصنيف مجموعات البيانات الجديدة والاستثناءات من قواعد الوصول","خطط معالجة فجوات جودة البيانات"],"cadence":"monthly","members":[{"en":"Director of Environmental Data Affairs, Chair","ar":"مدير شؤون البيانات البيئية، رئيساً"},{"en":"Director of Data Quality and Standards","ar":"مدير جودة البيانات والمعايير"},{"en":"Director of Data Systems","ar":"مدير نظم البيانات"},{"en":"Director of Data Governance and Security","ar":"مدير حوكمة البيانات وأمنها"},{"en":"Director of Digital","ar":"مدير الرقمنة"},{"en":"Regulatory and Legislative Review representative","ar":"ممثل المراجعة التنظيمية والتشريعية"}],"escalatesTo":"executive_committee","escalationEn":"Standards disputes and refusals to share data are escalated to the Executive Committee of the Office.","escalationAr":"تُرفع الخلافات على المعايير ورفض تبادل البيانات إلى اللجنة التنفيذية للمكتب.","sort":4}],"councilEnrichment":[{"matchNameEn":"Strategy Steering Committee","key":"strategy_steering_committee","decisionsEn":["Annual targets of the institutional strategy","Quarterly scorecard and risk register review","Reallocation of budget and people between Programme Strategy projects"],"decisionsAr":["المستهدفات السنوية للاستراتيجية المؤسسية","المراجعة الربعية لبطاقة الأداء وسجل المخاطر","إعادة توزيع الموازنة والكوادر بين مشاريع استراتيجية المكتب"],"escalatesTo":"secretary_general","escalationEn":"Blockers the committee cannot clear go to the Programme Director.","escalationAr":"تُرفع المعوقات التي تعجز اللجنة عن تذليلها إلى مدير البرنامج."},{"matchNameEn":"Strategy Office","key":"strategy_office","decisionsEn":["Maintenance of the results chain, the indicator cards and the process architecture","Acceptance of a reported actual as evidenced","Approval of interface changes on behalf of the Executive Committee of the Office"],"decisionsAr":["صيانة سلسلة النتائج وبطاقات المؤشرات وهيكل العمليات","قبول القيمة الفعلية المرفوعة بوصفها موثقة بالأدلة","اعتماد تعديلات الواجهات نيابة عن اللجنة التنفيذية للمكتب"],"escalatesTo":"strategy_steering_committee","escalationEn":"Amendments to goals, targets or ownership go to the Strategy Steering Committee.","escalationAr":"تُرفع تعديلات الأهداف أو المستهدفات أو الملكية إلى لجنة توجيه الاستراتيجية."},{"matchNameEn":"Department Focal Points Network","key":"focal_points","decisionsEn":["Status of projects and activities inside the department","Actuals entered for the department''s own indicators","New risks and lessons raised from the department"],"decisionsAr":["حالة المشاريع والأنشطة داخل الإدارة","القيم الفعلية المدخلة لمؤشرات الإدارة","المخاطر والدروس الجديدة المرفوعة من الإدارة"],"escalatesTo":"strategy_office","escalationEn":"Evidence disputes and cross-department dependencies go to the Strategy Office.","escalationAr":"تُرفع الخلافات على الأدلة والاعتماديات بين الإدارات إلى مكتب الاستراتيجية."}],"connectors":[{"from":"secretary_general","to":"council","kind":"reports_to"},{"from":"executive_committee","to":"secretary_general","kind":"escalates_to"},{"from":"strategy_steering_committee","to":"secretary_general","kind":"escalates_to"},{"from":"regulatory_review_panel","to":"executive_committee","kind":"escalates_to"},{"from":"data_governance_board","to":"executive_committee","kind":"escalates_to"},{"from":"strategy_office","to":"strategy_steering_committee","kind":"reports_to"},{"from":"focal_points","to":"strategy_office","kind":"reports_to"},{"from":"strategy_office","to":"executive_committee","kind":"advises"},{"from":"data_governance_board","to":"strategy_office","kind":"informs"},{"from":"secretary_general","to":"executive_committee","kind":"delegates_to"}],"isIllustrative":true}');
