INSERT INTO "signals" ("id", "title_en", "title_ar", "description_en", "description_ar", "source", "impact", "horizon", "node_ids_json", "document_id", "created_by", "created_at", "source_kind", "url", "publisher", "published_at", "signal_type", "sentiment", "confidence", "why_it_matters_en", "why_it_matters_ar", "triage_status", "triaged_by", "triaged_at", "converted_resource_type", "converted_resource_id", "scan_run_id", "raw_json", "source_excerpt", "embedding", "embedding_model") VALUES
('01M4D6BHRXWJ9R4YR60CEZ46Z5', 'Water scarcity pressures across the region', 'ضغوط ندرة المياه في المنطقة', 'Regional water stress indicators are worsening, adding urgency to desalination capacity planning, reuse and demand management.', 'تتفاقم مؤشرات الإجهاد المائي في المنطقة، مما يزيد إلحاح تخطيط طاقة التحلية وإعادة الاستخدام وإدارة الطلب.', 'scan of international reports', 'high', 'long', NULL, NULL, '01M4D6BHENXFYQ2E4HXXWJ52XS', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRXWCRW7BJWRXD3Y1YX', 'Increasing heat stress from climate change', 'تزايد الإجهاد الحراري الناجم عن تغير المناخ', 'Climate projections point to more frequent extreme heat days in the Gulf region, with implications for outdoor labour, energy demand and public health.', 'تشير الإسقاطات المناخية إلى تكرار أكبر لأيام الحرارة الشديدة في منطقة الخليج، بما يؤثر في العمل الخارجي والطلب على الطاقة والصحة العامة.', 'scan of international reports', 'high', 'long', NULL, NULL, '01M4D6BHENXFYQ2E4HXXWJ52XS', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRXKABNCZ1AWV87VD0F', 'Growing demand for high-integrity carbon markets', 'تنامي الطلب على أسواق الكربون عالية النزاهة', 'Voluntary and compliance carbon markets are tightening integrity expectations, which shapes how national offsets and removals are valued.', 'تتشدد أسواق الكربون الطوعية والإلزامية في معايير النزاهة، مما يؤثر في تقييم المقاصات والإزالات الوطنية.', 'scan of international reports', 'medium', 'mid', NULL, NULL, '01M4D6BGHAKBD28V6BPQ7S7XE3', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRXBBWKT07A7VNCBG2D', 'Satellite monitoring of vegetation and water', 'رصد الغطاء النباتي والمياه بالأقمار الصناعية', 'Earth observation costs are falling, making operational vegetation and water monitoring feasible at national scale.', 'تنخفض كلفة رصد الأرض، مما يجعل الرصد التشغيلي للغطاء النباتي والمياه ممكناً على المستوى الوطني.', 'scan of international reports', 'medium', 'near', NULL, NULL, '01M4D6BHERXH0T9A327SBQDQP6', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRYVTQ8KG8QDHRADHBG', 'Expansion of generative AI in public sector service delivery', 'توسع الذكاء الاصطناعي التوليدي في تقديم الخدمات الحكومية', 'Governments are piloting generative AI assistants for regulatory guidance, prompting questions about accuracy, oversight and trust.', 'تجرّب الحكومات مساعدين بالذكاء الاصطناعي التوليدي للإرشاد التنظيمي، مما يثير أسئلة عن الدقة والرقابة والثقة.', 'scan of international reports', 'high', 'near', NULL, NULL, '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRY8ZGJWTHARE45XVPE', 'Circular economy requirements spreading in packaging', 'انتشار متطلبات الاقتصاد الدائري في التغليف', 'Producer responsibility rules for packaging are spreading across markets, shaping waste and recycling policy.', 'تنتشر قواعد مسؤولية المنتج في التغليف عبر الأسواق، مما يشكل سياسات النفايات وإعادة التدوير.', 'scan of international reports', 'medium', 'mid', NULL, NULL, '01M4D6BHEV9G5W4Q3XS5WPTZNG', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRY6ZQN4PHNT265BVAK', 'Dust and sandstorm intensity', 'شدة الغبار والعواصف الرملية', 'Land degradation and drought can raise dust event frequency, affecting air quality and public health.', 'قد يزيد تدهور الأراضي والجفاف من تكرار أحداث الغبار، بما يؤثر في جودة الهواء والصحة العامة.', 'scan of international reports', 'medium', 'mid', NULL, NULL, '01M4D6BHF5XQA06C5Z707P3NMH', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRYMMC1WA3QCCWTJDHE', 'Volatile food import prices', 'تقلب أسعار واردات الغذاء', 'Global food price swings and shipping disruptions can affect staple availability and import costs.', 'قد تؤثر تقلبات أسعار الغذاء العالمية واضطرابات الشحن في توافر السلع الأساسية وتكاليف الاستيراد.', 'scan of international reports', 'medium', 'near', NULL, NULL, '01M4D6BHEQP10YDP9M2S6Q22GQ', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRY9DEWXCF1MKYWBTVD', 'Stricter ESG disclosure expectations', 'تشدد توقعات الإفصاح البيئي والاجتماعي والحوكمي', 'Investors and regulators increasingly expect structured environmental disclosure, raising demand for reliable emissions and water data.', 'يتوقع المستثمرون والجهات التنظيمية بصورة متزايدة إفصاحاً بيئياً منظماً، مما يرفع الطلب على بيانات موثوقة للانبعاثات والمياه.', 'scan of international reports', 'medium', 'mid', NULL, NULL, '01M4D6BHENT806953T1KMXG22P', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BHRYC3H2ZVJ7VX2B31RT', 'Cybersecurity threats targeting environmental monitoring infrastructure', 'تهديدات الأمن السيبراني التي تستهدف بنية الرصد البيئي', 'Reports flag rising attacks on utilities and monitoring infrastructure, underscoring the need for resilient systems.', 'تشير التقارير إلى تصاعد الهجمات على المرافق والبنية التحتية للرصد، مما يؤكد الحاجة إلى نظم مرنة.', 'scan of international reports', 'high', 'near', NULL, NULL, '01M4D6BHENT806953T1KMXG22P', '2026-10-08T07:23:58.764Z', 'manual', NULL, NULL, NULL, 'policy', 'neutral', NULL, NULL, NULL, 'new', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('01M4D6BJ0EF1R5SWPGT4ZDC05R', 'Desalination operators test energy recovery upgrades', 'مشغلو التحلية يجربون تحديثات استرداد الطاقة', 'Illustrative signal. Operators across the region are trialling energy recovery and membrane upgrades to cut the electricity used per cubic metre of desalinated water.', 'إشارة توضيحية. يجرب المشغلون في المنطقة تحديثات استرداد الطاقة والأغشية لخفض الكهرباء المستهلكة لكل متر مكعب من المياه المحلاة.', 'Demo scan: regional press', 'high', 'mid', NULL, NULL, '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-10-06T07:24:00.398Z', 'web_search', NULL, 'Demo scan: regional press', '2026-10-06', 'technology', 'positive', 0.82, 'Lower energy intensity directly supports the Water Security theme and the cost of supply.', 'خفض كثافة الطاقة يدعم محور الأمن المائي مباشرة ويقلل كلفة الإمداد.', 'accepted', '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-10-08T07:23:58.764Z', NULL, NULL, NULL, NULL, NULL, '\', 'local-hash-256'),
('01M4D6BJ0FMJR79EZ8GZG3886F', 'Studies point to rising reuse of treated wastewater in irrigation', 'دراسات تشير إلى ارتفاع إعادة استخدام مياه الصرف المعالجة في الري', 'Illustrative signal. Research on arid-region farming shows growing interest in treated wastewater for non-food crops and landscaping, with water quality monitoring as the main condition.', 'إشارة توضيحية. تُظهر دراسات في الزراعة بالمناطق الجافة اهتماماً متزايداً بالمياه المعالجة للمحاصيل غير الغذائية والمسطحات الخضراء، مع اشتراط رصد جودة المياه.', 'Demo scan: research and think tanks', 'medium', 'mid', NULL, NULL, '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-10-03T07:24:00.399Z', 'web_search', NULL, 'Demo scan: research and think tanks', '2026-10-03', 'research', 'positive', 0.78, 'Reuse expands supply without new abstraction.', 'إعادة الاستخدام توسع الإمداد دون سحب جديد.', 'accepted', '01M4D6BGHA1ANAZV0TK6CR8SAW', '2026-10-08T07:23:58.764Z', NULL, NULL, NULL, NULL, NULL, '\', 'local-hash-256'),
