('01M4D6BHNJ6Z867XM46K4A18FQ', '01M4D6BHKAWCVWDFFVHF440A5P', '01M4D6BGHA1ANAZV0TK6CR8SAW', 'on_track', 60, 'Delivery review completed for Landfill Gas Capture. Milestones tracked against the approved plan.', 'اكتملت مراجعة التنفيذ لـالتقاط غاز المرادم. وتجري متابعة المعالم وفق الخطة المعتمدة.', NULL, '[{"text_en":"Confirm next quarter milestones with the delivery office","text_ar":"تأكيد معالم الربع القادم مع مكتب التنفيذ"}]', NULL, '2026-Q3', '2026-10-02T07:24:00.050Z'),
('01M4D6BHNJDZRX9E96Y7Y9NCZA', '01M4D6BHKAJFR1KTGYP8E2Q1VE', '01M4D6BGHAKBD28V6BPQ7S7XE3', 'on_track', 70, 'Delivery review completed for Emission Control Programme. Milestones tracked against the approved plan.', 'اكتملت مراجعة التنفيذ لـبرنامج مكافحة الانبعاثات. وتجري متابعة المعالم وفق الخطة المعتمدة.', NULL, '[{"text_en":"Confirm next quarter milestones with the delivery office","text_ar":"تأكيد معالم الربع القادم مع مكتب التنفيذ"}]', NULL, '2026-Q3', '2026-09-26T07:24:00.050Z'),
