('01M4D6BHNJCDD1GBNYMWM7PWZ0', '01M4D6BHKBXKV8SPDTGMNE4TFS', '01M4D6BGHA1ANAZV0TK6CR8SAW', 'on_track', 90, 'Delivery review completed for Environmental Investment Pipeline Platform. Milestones tracked against the approved plan.', 'اكتملت مراجعة التنفيذ لـمنصة مسار الاستثمارات البيئية. وتجري متابعة المعالم وفق الخطة المعتمدة.', NULL, '[{"text_en":"Confirm next quarter milestones with the delivery office","text_ar":"تأكيد معالم الربع القادم مع مكتب التنفيذ"}]', NULL, '2026-Q3', '2026-09-10T07:24:00.050Z');
INSERT INTO "strategy_editions" ("id", "code", "name_en", "name_ar", "period_from", "period_to", "status", "summary_en", "summary_ar", "source_document_id", "is_default") VALUES
('01M4D6BHK86SG4TY05B09H7FDR', 'nes3', 'National Environment Strategy (NES) Delivery Plan 2024-2030', 'خطة تنفيذ الاستراتيجية الوطنية للبيئة 2024-2030', 2024, 2030, 'live', 'The current delivery plan of the Programme Office for the National Environment Strategy (NES). It organises the work into seven environment themes aligned with Saudi Vision 2030 (a Vibrant Society, a Thriving Economy and an Ambitious Nation): Water Security, Agriculture and Food Security, Biodiversity and Land, Waste and Circular Economy, Air Quality, Climate and Environment, and Regulatory Compliance and Enforcement. Each theme carries targets, programme clusters, initiatives and projects, supported by three cross-cutting enablers. Targets taken from the Saudi Green Initiative are marked as sourced; all other targets, dates, budgets and statuses are an illustrative demo model and are flagged as such.', 'خطة التنفيذ الحالية لمكتب البرنامج للاستراتيجية الوطنية للبيئة. وهي تنظم العمل في سبعة محاور بيئية متوائمة مع رؤية السعودية 2030 (مجتمع حيوي واقتصاد مزدهر ووطن طموح): الأمن المائي، والأمن الغذائي والزراعة، والتنوع الأحيائي والأراضي، والنفايات والاقتصاد الدائري، وجودة الهواء، والمناخ والبيئة، والامتثال التنظيمي والإنفاذ. ويشمل كل محور مستهدفات وعناقيد برامج ومبادرات ومشاريع، تدعمها ثلاث ممكنات شاملة. وتُعرض المستهدفات المأخوذة من مبادرة السعودية الخضراء بوصفها موثقة، أما سائر المستهدفات والتواريخ والميزانيات والحالات فهي نموذج توضيحي لأغراض العرض وتُوسم بذلك.', NULL, 1),
('01M4D6BHK85JYBYXC8YQPA6HYW', 'nes2', 'Environment Sector Programme 2018-2023 (illustrative earlier cycle)', 'برنامج قطاع البيئة 2018-2023 (دورة سابقة توضيحية)', 2018, 2023, 'archived', 'An illustrative model of the earlier planning cycle that preceded the current delivery plan. It groups twelve sector strategies across water, agriculture, biodiversity, land, waste, air, climate and environmental governance, and is used in the demo to show how scope carried forward into the current plan. It is not a published government document.', 'نموذج توضيحي لدورة إعداد الخطط السابقة التي سبقت خطة التنفيذ الحالية. ويجمع اثنتي عشرة استراتيجية قطاعية في المياه والزراعة والتنوع الأحيائي والأراضي والنفايات والهواء والمناخ والحوكمة البيئية، ويُستخدم في العرض لبيان كيف انتقل النطاق إلى الخطة الحالية. وهو ليس وثيقة حكومية منشورة.', NULL, 0),
('01M4D6BHK938Y07R0NFSW5T1C6', 'nes1', 'Foundations Phase 2012-2017 (illustrative)', 'مرحلة التأسيس 2012-2017 (توضيحية)', 2012, 2017, 'archived', 'An illustrative model of the foundations phase in which core water, agriculture, wildlife and environmental functions were set up and first sector plans were drafted. It is used in the demo to show lineage across planning cycles and is not a published government document.', 'نموذج توضيحي لمرحلة التأسيس التي أُرسيت فيها المهام الأساسية في المياه والزراعة والحياة الفطرية والبيئة وصيغت فيها الخطط القطاعية الأولى. ويُستخدم في العرض لبيان التسلسل عبر دورات إعداد الخطط، وهو ليس وثيقة حكومية منشورة.', NULL, 0);
INSERT INTO "strategy_nodes" ("id", "edition_id", "parent_id", "node_type", "code", "title_en", "title_ar", "description_en", "description_ar", "owner_user_id", "owner_entity_name", "status", "start_date", "end_date", "budget_qar", "funding_source", "sort", "source_ref", "verified", "created_at", "updated_at") VALUES
('01M4D6BHK9576VE73AKHSCPJCR', '01M4D6BHK86SG4TY05B09H7FDR', NULL, 'outcome', 'O1', 'Water Security', 'الأمن المائي', 'Secure, efficient and sustainable water supply through demand management, network efficiency, desalination, wastewater reuse and groundwater protection, in line with the National Water Strategy 2030.', 'أمن إمدادات المياه وكفاءتها واستدامتها عبر إدارة الطلب وكفاءة الشبكات والتحلية وإعادة استخدام مياه الصرف وحماية المياه الجوفية، بما يتسق مع الاستراتيجية الوطنية للمياه 2030.', NULL, 'Ministry of Environment, Water and Agriculture', 'on_track', '2024-01-01', '2030-12-31', NULL, NULL, 1, 'Illustrative demo model (themes aligned with Saudi Vision 2030)', 0, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHK9K95DGK4RSBSQKWH0', '01M4D6BHK86SG4TY05B09H7FDR', NULL, 'outcome', 'O2', 'Agriculture and Food Security', 'الأمن الغذائي والزراعة', 'Productive and water-efficient agriculture, resilient food supply chains and diversified food trade that protect food security while easing pressure on groundwater.', 'زراعة منتجة وكفؤة في استخدام المياه وسلاسل إمداد غذائي مرنة وتجارة غذائية متنوعة تحمي الأمن الغذائي وتخفف الضغط على المياه الجوفية.', NULL, 'Ministry of Environment, Water and Agriculture', 'on_track', '2024-01-01', '2030-12-31', NULL, NULL, 2, 'Illustrative demo model (themes aligned with Saudi Vision 2030)', 0, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
('01M4D6BHK985WAR19CDE822C55', '01M4D6BHK86SG4TY05B09H7FDR', NULL, 'outcome', 'O3', 'Biodiversity and Land', 'التنوع الأحيائي والأراضي', 'Protect species and habitats, expand protected areas, restore vegetation cover and combat desertification, contributing to the Saudi Green Initiative.', 'حماية الأنواع والموائل وتوسيع المحميات واستعادة الغطاء النباتي ومكافحة التصحر، إسهاماً في مبادرة السعودية الخضراء.', NULL, 'National Center for Wildlife', 'on_track', '2024-01-01', '2030-12-31', NULL, NULL, 3, 'Illustrative demo model (themes aligned with Saudi Vision 2030)', 0, '2026-10-08T07:23:58.764Z', '2026-10-08T07:23:58.764Z'),
